    #[test]
    fn get_annotation_mirrors_exposes_explicit_values() {
        let mut fixture = Fixture::new();
        let annotation = fixture.class("p.A", flags::ANNOTATION as i64);
        let members = fixture.members(annotation);
        let int_type = fixture.syms.int_type;
        let string_type = fixture.syms.string_type;
        let value_method = fixture.method(annotation, "value", int_type);
        let name_method = fixture.method(annotation, "name", string_type);
        fixture.ctx.scope_enter(members, value_method);
        fixture.ctx.scope_enter(members, name_method);
        let default_value = fixture.int_attribute(7);
        let default_name = fixture.string_attribute("d");
        fixture.default_value(value_method, default_value);
        fixture.default_value(name_method, default_name);
        let class = fixture.class("p.C", 0);
        let explicit = fixture.int_attribute(3);
        let attribute = fixture.compound_attribute(annotation, vec![(value_method, explicit)]);
        fixture.annotate(class, attribute);
        let mirrors = crate::model::annotation_mirrors::annotation_mirrors(
            &mut fixture.ctx,
            &fixture.syms,
            class,
        );
        assert_eq!(mirrors.len(), 1);
        let mirror = &mirrors[0];
        let annotation_element = mirror.get_annotation_type().as_element();
        assert_eq!(annotation_element.get_kind(), crate::code::symbol::ElementKind::ANNOTATION_TYPE);
        assert!(annotation_element
            .get_simple_name()
            .content_equals(&JavaString::from("A")));
        let enclosed = annotation_element.get_enclosed_elements();
        assert_eq!(enclosed.len(), 2);
        let values = mirror.get_element_values();
        assert_eq!(values.len(), 1, "default values are not part of element values");
        let (method, value) = &values[0];
        assert!(method
            .get_simple_name()
            .content_equals(&JavaString::from("value")));
        assert!(matches!(value.get_value(), javac_tools::lang::model::element::annotation_value::Value::Integer(3)));
        assert!(method.is_default());
        let default = method.get_default_value().expect("default value");
        assert!(matches!(
            default.get_value(),
            javac_tools::lang::model::element::annotation_value::Value::Integer(7)
        ));
        let declared = mirror.get_annotation_type();
        assert_eq!(declared.get_kind(), javac_tools::lang::model::type_::type_kind::TypeKind::DECLARED);
        assert!(declared.get_type_arguments().is_empty());
    }
    fn compile_annotation_source(source: &str) -> (crate::main::mini_compiler::MiniCompiler, Vec<crate::main::mini_compiler::CompiledClass>) {
        use javac_tools::tools::standard_java_file_manager::StandardJavaFileManager;
        let root = std::env::temp_dir().join(format!(
            "rust-javac-annotation-e2e-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        ));
        let out = root.join("out");
        std::fs::create_dir_all(&out).expect("out");
        let src = root.join("src");
        std::fs::create_dir_all(&src).expect("src");
        let file = src.join("A.java");
        std::fs::write(&file, source).expect("write");
        let mut compiler = crate::main::mini_compiler::MiniCompiler::new(&out);
        let sp = javac_tools::tools::standard_location::StandardLocation::location_for(
            &javac_strings::JavaString::from("SOURCE_PATH"),
        );
        compiler
            .file_manager
            .set_location(&*sp, Some(&[src]))
            .expect("source path");
        let compiled = compiler
            .compile_files(&[file])
            .expect("annotation compilation");
        assert_eq!(compiler.error_count(), 0);
        (compiler, compiled)
    }

    fn has_bytes(bytes: &[u8], needle: &[u8]) -> bool {
        bytes.windows(needle.len()).any(|window| window == needle)
    }

    #[test]
    fn e2e_annotation_interface_and_usage_compile() {
        let source = "@interface A { int value() default 7; String name() default \"d\"; }\n@A(3) class C {}\n";
        let (mut compiler, compiled) = compile_annotation_source(source);
        let names: Vec<&str> = compiled.iter().map(|class| class.name.as_str()).collect();
        assert!(names.contains(&"A"), "generated: {names:?}");
        assert!(names.contains(&"C"), "generated: {names:?}");
        let a_bytes = compiled
            .iter()
            .find(|class| class.name == "A")
            .map(|class| class.bytes.as_slice())
            .expect("A.class");
        assert!(
            has_bytes(a_bytes, b"AnnotationDefault"),
            "the annotation element defaults must be written"
        );
        let c_bytes = compiled
            .iter()
            .find(|class| class.name == "C")
            .map(|class| class.bytes.as_slice())
            .expect("C.class");
        assert!(
            has_bytes(c_bytes, b"RuntimeInvisibleAnnotations") || has_bytes(c_bytes, b"RuntimeVisibleAnnotations"),
            "the @A annotation must be written"
        );
        let mut syms = compiler.syms.borrow_mut();
        let c_symbol = syms
            .class_by_flat_name(&JavaString::from("C"))
            .expect("class C symbol");
        let attribute = get_attribute(
            &mut compiler.ctx,
            &syms,
            &compiler.types,
            c_symbol,
            &Class::with_flat_name(JavaString::from("A")),
        )
        .expect("attached @A annotation");
        let proxy = generate_annotation(&mut compiler.ctx, attribute);
        assert!(matches!(
            proxy.member_value(&JavaString::from("value")),
            Some(AnnotationValueProxy::Integer(3))
        ));
        match proxy.member_value(&JavaString::from("name")) {
            Some(AnnotationValueProxy::String(value)) => {
                assert_eq!(value, JavaString::from("d"))
            }
            _ => panic!("default value from the annotation interface"),
        }
    }
